html:
{% import "costeo_yelke/templates/print/oc_yelke.html" as oc %}
{#- Reporte final del costeo: análisis interno, plan contra real, sin IVA.
    Los números los prepara reporte_impresion.reporte_final_impresion (método jinja,
    hooks.py) con costeo_api.get_reporte_final -- los mismos de la pantalla. Aquí solo
    se pintan. wkhtmltopdf: barras y gráficas con tablas, sin flex ni grid. -#}
{%- set R = reporte_final_impresion(doc) -%}
{%- set e = R.estimado -%}{%- set real = R.real -%}{%- set op = R.op -%}
{%- macro mx(v) -%}{%- if v < -0.005 -%}−${{ "{:,.2f}".format(-v) }}{%- else -%}${{ "{:,.2f}".format(v if v > 0.005 else 0) }}{%- endif -%}{%- endmacro -%}
{%- macro dif(v) -%}{%- if v > 0.005 -%}+${{ "{:,.2f}".format(v) }}{%- elif v < -0.005 -%}−${{ "{:,.2f}".format(-v) }}{%- else -%}$0.00{%- endif -%}{%- endmacro -%}
{#- Color de una diferencia: favorable si `bueno` > 0. -#}
{%- macro tono(bueno) -%}{%- if bueno > 0.5 -%}yk-bien{%- elif bueno < -0.5 -%}yk-mal{%- endif -%}{%- endmacro -%}
{%- macro num(v, d=0) -%}{{ ("{:,.%df}" % d).format(v or 0) }}{%- endmacro -%}
{%- macro unidad(uom) -%}{%- set n = (uom or "").split(" - ")[-1] | lower -%}{{ {"metro": "m", "pieza": "pzas", "kilogramo": "kg", "litro": "L"}.get(n, n) }}{%- endmacro -%}
{{ oc.estilos() }}
<style>
.yk-bien { color: #0f8a5f !important; }
.yk-mal { color: #c0392b !important; }
.yk-conf { margin: -2mm 0 4mm; font-size: 7pt; color: #777; letter-spacing: 0.4px; }
.yk-conf b { color: #e65a0b; letter-spacing: 1.4px; text-transform: uppercase; font-size: 6.5pt; margin-right: 2mm; }
/* Indicadores: cajas en una tabla con bordes finos. */
.yk-kpi { width: 100%; border-collapse: collapse; table-layout: fixed; margin-bottom: 3mm; }
.yk-kpi td { border: 0.3mm solid #e4e4e4 !important; padding: 2.6mm 3mm !important; vertical-align: top; }
.yk-kpi .t { font-size: 6.5pt; color: #777; letter-spacing: 1px; text-transform: uppercase; }
.pdf-container .yk-kpi .v { font-size: 13pt; font-weight: 600; color: #111; margin-top: 0.8mm; white-space: nowrap; }
.yk-kpi .s { font-size: 7pt; color: #777; margin-top: 0.4mm; }
/* Barras. */
.yk-barras { width: 100%; border-collapse: collapse; margin-bottom: 1mm; }
.yk-barras td { padding: 0.8mm 0 !important; border: 0 !important; vertical-align: middle; font-size: 7.4pt; }
.yk-barras td.l { width: 26mm; color: #555; }
.yk-barras td.n { width: 30mm; text-align: right; white-space: nowrap; }
.yk-pista { background: #f4f4f5; height: 3.2mm; width: 100%; }
.yk-pista div { height: 3.2mm; }
.yk-plan { background: #d4d4d8; }
.yk-real { background: #ff6b15; }
.yk-pila { width: 100%; border-collapse: collapse; table-layout: fixed; margin: 1mm 0 1.5mm; }
.yk-pila td { height: 4mm; padding: 0 !important; border: 0 !important; border-right: 0.5mm solid #fff !important; }
.yk-ley { font-size: 7pt; color: #555; margin-bottom: 3mm; }
.yk-ley span.c { display: inline-block; width: 2.4mm; height: 2.4mm; margin: 0 1mm -0.3mm 0; }
.yk-ley span.i { margin-right: 4mm; }
.yk-dos { width: 100%; border-collapse: collapse; table-layout: fixed; }
.yk-dos > tbody > tr > td { vertical-align: top; padding: 0 !important; border: 0 !important; }
.yk-dos > tbody > tr > td + td { padding-left: 6mm !important; }
.yk-sub2 { font-size: 7.6pt; font-weight: 600; color: #222; margin: 2.5mm 0 1mm; }
.items-table td.n, .items-table th.n { text-align: right; white-space: nowrap; }
.items-table tr.tot td { font-weight: 600; border-top: 0.4mm solid #111 !important; }
.items-table .nota { display: block; font-size: 6.6pt; color: #888; }
.yk-firmas-int { width: 100%; border-collapse: collapse; margin-top: 12mm; page-break-inside: avoid; }
.yk-firmas-int td { width: 50%; padding: 0 8mm !important; border: 0 !important; text-align: center; font-size: 7.4pt; color: #555; }
.yk-firmas-int .linea { border-top: 0.3mm solid #111; padding-top: 1.5mm; }
.yk-nota-fin { margin-top: 4mm; font-size: 6.8pt; color: #888; line-height: 1.5; }
</style>
{#- En el encabezado va la fecha en que se emite el reporte, no la del costeo. -#}
{%- set dh = doc.as_dict() -%}{%- set hoy = frappe.utils.nowdate() -%}{%- set _ = dh.update({"transaction_date": hoy, "posting_date": hoy, "fecha": hoy}) -%}
{{ oc.membrete_encabezado(dh, no_letterhead, print_settings, "Reporte final") }}
<div class="pdf-container">

<div class="yk-conf"><b>Uso interno</b>Análisis de rentabilidad del proyecto · plan del costeo contra lo real de los documentos validados · montos sin IVA</div>

{{ oc.datos(doc,
    {"etiqueta": "Cliente", "nombre": doc.cliente, "rfc": rfc_tercero("Customer", doc.cliente), "direccion": []},
    [("Proyecto", doc.get("titulo")),
     ("Orden de venta", R.sales_order),
     ("Factura de venta", real.sales_invoice or "Sin factura"),
     ("Prendas", num(R.prendas)),
     ("Estado del proceso", "Cerrado" if R.completo else "Con documentos pendientes")]) }}

{{ oc.seccion("Resumen") }}
<table class="yk-kpi">
  <tr>
    <td><div class="t">Venta</div><div class="v">{{ mx(real.ingreso) if R.facturado else "Sin factura" }}</div>
      <div class="s">plan {{ mx(e.venta_total) }}</div></td>
    <td><div class="t">Costo total</div><div class="v">{{ mx(real.costo_total) }}</div>
      <div class="s">plan {{ mx(e.costo_total) }} · <span class="{{ tono(-R.variacion.costo_monto) }}">{{ "%+.1f" % R.variacion.costo_pct }}%</span></div></td>
    <td><div class="t">Margen</div><div class="v">{{ "%.1f" % real.rentabilidad_pct if R.facturado else "—" }}{% if R.facturado %}%{% endif %}</div>
      <div class="s">plan {{ "%.1f" % e.rentabilidad_pct }}%{% if R.facturado %} · <span class="{{ tono(R.variacion.rentabilidad_pct_puntos) }}">{{ "%+.1f" % R.variacion.rentabilidad_pct_puntos }} pts</span>{% endif %}</div></td>
    <td><div class="t">Costo por prenda</div><div class="v">{{ mx(R.costo_unit) }}</div>
      <div class="s">plan {{ mx(R.costo_unit_plan) }}{% if R.facturado %} · deja {{ mx(R.util_unit) }}{% endif %}</div></td>
  </tr>
  <tr>
    <td><div class="t">Utilidad</div><div class="v">{{ mx(real.rentabilidad_monto) if R.facturado else "—" }}</div>
      <div class="s">plan {{ mx(e.rentabilidad_monto) }}</div></td>
    <td><div class="t">Entrega al cliente</div>
      <div class="v">{% if op.dias_entrega is not none %}{{ op.dias_entrega }} días{% else %}Sin entregar{% endif %}</div>
      <div class="s">{% if op.dias_atraso is not none %}{% if op.dias_atraso > 0 %}<span class="yk-mal">{{ op.dias_atraso }} días tarde</span>{% elif op.dias_atraso < 0 %}<span class="yk-bien">{{ -op.dias_atraso }} días antes</span>{% else %}en la fecha{% endif %} del compromiso{% endif %}</div></td>
    <td><div class="t">Aprovechamiento de material</div>
      <div class="v">{{ ("%.1f" % R.aprovechamiento) ~ "%" if R.aprovechamiento is not none else "—" }}</div>
      <div class="s">sobrante en inventario {{ mx(real.material_sobrante) }}</div></td>
    <td><div class="t">Por cobrar / por pagar</div>
      <div class="v">{{ mx(op.por_cobrar or 0) }}</div>
      <div class="s">{% if op.vence_cobro %}vence {{ fecha_corta(op.vence_cobro) }} · {% endif %}por pagar {{ mx(op.por_pagar or 0) }}</div></td>
  </tr>
</table>

{{ oc.seccion("Comparativo visual") }}
<table class="yk-dos"><tr>
<td>
  <div class="yk-sub2">Costo total</div>
  <table class="yk-barras">
    <tr><td class="l">Plan</td><td><div class="yk-pista"><div class="yk-plan" style="width: {{ R.ancho_costo_plan }}%"></div></div></td><td class="n">{{ mx(e.costo_total) }}</td></tr>
    <tr><td class="l">Real</td><td><div class="yk-pista"><div class="yk-real" style="width: {{ R.ancho_costo_real }}%"></div></div></td><td class="n"><b>{{ mx(real.costo_total) }}</b></td></tr>
  </table>
  <div class="yk-sub2">Por concepto <span style="font-weight:400; color:#888">· gris plan, naranja real</span></div>
  <table class="yk-barras">
    {%- for c in R.costos %}
    <tr><td class="l" rowspan="2">{{ c.label }}</td><td><div class="yk-pista"><div class="yk-plan" style="width: {{ c.ancho_plan }}%"></div></div></td><td class="n" style="color:#888">{{ mx(c.plan) }}</td></tr>
    <tr><td><div class="yk-pista"><div class="yk-real" style="width: {{ c.ancho_real }}%"></div></div></td><td class="n">{{ mx(c.real) }}</td></tr>
    {%- endfor %}
  </table>
</td>
<td>
  <div class="yk-sub2">¿En qué se fue el costo real?</div>
  <table class="yk-pila"><tr>{% for s in R.composicion %}<td style="width: {{ s.pct }}%; background: {{ s.color }}"></td>{% endfor %}</tr></table>
  <div class="yk-ley">{% for s in R.composicion %}<span class="i"><span class="c" style="background: {{ s.color }}"></span>{{ s.label }} <b>{{ "%.1f" % s.pct }}%</b></span>{% endfor %}</div>
  <div class="yk-sub2">De cada peso de venta</div>
  <table class="yk-pila"><tr>{% for s in R.peso_venta %}<td style="width: {{ s.pct }}%; background: {{ s.color }}"></td>{% endfor %}</tr></table>
  <div class="yk-ley">{% for s in R.peso_venta %}<span class="i"><span class="c" style="background: {{ s.color }}"></span>{{ s.label }} <b>${{ "%.2f" % (s.pct / 100) }}</b></span>{% endfor %}</div>
  {%- if R.facturado %}
  <div class="yk-sub2">De la utilidad estimada a la real</div>
  <table class="items-table" style="margin-bottom:0">
    <tbody>
      <tr><td>Utilidad estimada</td><td class="n">{{ mx(e.rentabilidad_monto) }}</td></tr>
      {%- for p in R.puente %}
      <tr><td style="padding-left:5mm">{{ p.label }}</td><td class="n {{ tono(p.v) }}">{{ dif(p.v) }}</td></tr>
      {%- endfor %}
      <tr class="tot"><td>Utilidad real</td><td class="n">{{ mx(real.rentabilidad_monto) }}</td></tr>
    </tbody>
  </table>
  {%- endif %}
</td>
</tr></table>

<div style="page-break-inside: avoid">
{{ oc.seccion("Costos") }}
<table class="items-table">
  <thead><tr><th>Concepto</th><th class="n">Plan</th><th class="n">Real</th><th class="n">Diferencia</th><th class="n">Por prenda</th><th class="n">% del costo</th></tr></thead>
  <tbody>
    {%- for c in R.costos %}
    <tr><td>{{ c.label }}{% if c.nota %}<span class="nota">{{ c.nota }}</span>{% endif %}</td>
      <td class="n" style="color:#777">{{ mx(c.plan) }}</td><td class="n">{{ mx(c.real) }}</td>
      <td class="n {{ tono(-c.dif) }}">{{ dif(c.dif) }}</td><td class="n">{{ mx(c.por_prenda) }}</td><td class="n">{{ "%.1f" % c.pct }}%</td></tr>
    {%- endfor %}
    <tr class="tot"><td>Total</td><td class="n">{{ mx(e.costo_total) }}</td><td class="n">{{ mx(real.costo_total) }}</td>
      <td class="n {{ tono(-R.variacion.costo_monto) }}">{{ dif(R.variacion.costo_monto) }}</td><td class="n">{{ mx(R.costo_unit) }}</td><td class="n">100%</td></tr>
  </tbody>
</table>
</div>

{%- set mats = (R.resumen or {}).get("materiales") or [] %}
{%- if mats %}
{{ oc.seccion("Materia prima") }}
<table class="items-table">
  <thead><tr><th>Material</th><th class="n">Plan</th><th class="n">Consumido</th><th class="n">Comprado</th><th class="n">Sobra</th><th class="n">Precio plan / real</th><th class="n">Por precio</th><th class="n">Por consumo</th></tr></thead>
  <tbody>
    {%- for m in mats %}
    <tr><td>{{ m.item_name }}<span class="nota">{{ m.proveedor_real or m.proveedor_plan }}</span></td>
      <td class="n">{{ num(m.plan_qty, 2) }} {{ unidad(m.uom) }}</td>
      <td class="n"><b>{{ num(m.consumido_qty, 2) }} {{ unidad(m.uom) }}</b></td>
      <td class="n">{{ num(m.comprado_qty, 2) }} {{ unidad(m.uom) }}</td>
      <td class="n">{{ num(m.sobrante_qty, 2) }} {{ unidad(m.uom) }}</td>
      <td class="n">{% if m.precio_plan < 1 %}${{ "%.4f" % m.precio_plan }} / ${{ "%.4f" % m.precio_real }}{% else %}{{ mx(m.precio_plan) }} / {{ mx(m.precio_real) }}{% endif %}</td>
      <td class="n {{ tono(-m.efecto_precio) }}">{{ dif(m.efecto_precio) }}</td>
      <td class="n {{ tono(-m.efecto_consumo) }}">{{ dif(m.efecto_consumo) }}</td></tr>
    {%- endfor %}
  </tbody>
</table>
{%- endif %}

{%- set servs = (R.resumen or {}).get("servicios") or [] %}
<table class="yk-dos"><tr>
<td style="width:62%">
{%- if servs %}
{{ oc.seccion("Maquila") }}
<table class="items-table">
  <thead><tr><th>Servicio · taller</th><th class="n">Prendas</th><th class="n">Plan</th><th class="n">Real</th><th class="n">Diferencia</th></tr></thead>
  <tbody>
    {%- for s in servs %}
    <tr><td>{{ (s.servicio_nombre or "").rstrip("-") }}<span class="nota">{{ s.proveedor }}</span></td>
      <td class="n">{{ num(s.qty) }}</td><td class="n" style="color:#777">{{ mx(s.estimado) }}</td><td class="n">{{ mx(s.real) }}</td>
      <td class="n {{ tono(s.estimado - s.real) }}">{{ dif(s.real - s.estimado) }}</td></tr>
    {%- endfor %}
  </tbody>
</table>
{%- endif %}
</td>
<td>
{{ oc.seccion("Fletes") }}
<table class="items-table">
  <tbody>
    <tr><td>Compra de materia prima</td><td class="n">{{ mx(real.flete_materiales) }}</td></tr>
    <tr><td>Envío a talleres</td><td class="n">{{ mx(real.flete_taller_ida) }}</td></tr>
    <tr><td>Regreso de talleres</td><td class="n">{{ mx(real.flete_taller_regreso) }}</td></tr>
    <tr><td>Entrega al cliente</td><td class="n">{{ mx(real.flete_cliente) }}</td></tr>
    <tr class="tot"><td>Total<span class="nota">plan {{ mx(e.shipping_total) }}</span></td><td class="n">{{ mx(R.fletes_total) }}</td></tr>
  </tbody>
</table>
</td>
</tr></table>

<div class="yk-nota-fin">
  Real = documentos validados: facturas de proveedores y de venta, recibos, envíos y remisiones. La materia prima real es lo
  comprado menos el sobrante que sigue en inventario. Gastos al {{ "%.1f" % e.overhead_pct_promedio }}% del costo
  directo real. Montos sin IVA.{% if not R.completo %} <b>Con documentos pendientes: los números reales todavía pueden cambiar.</b>{% endif %}
</div>

<table class="yk-firmas-int">
  <tr>
    <td><div class="linea"><b>Elaboró</b><br>{{ frappe.get_fullname() }}</div></td>
    <td><div class="linea"><b>Revisó</b><br>Dirección</div></td>
  </tr>
</table>

</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
